(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fa"] = {"ui":{"skip":"پرش به محتوا","back":"← بازگشت به AI-gile","lang.button":"زبان: {name}","lang.dialog":"یک زبان انتخاب کنید","lang.search":"جستجوی زبان‌ها","lang.none":"هیچ زبانی پیدا نشد","lang.notYet":"{name} هنوز ترجمه نشده است","theme.aria":"جابه‌جایی بین پوستهٔ روشن و تیره","theme.toLight":"رفتن به پوستهٔ روشن","theme.toDark":"رفتن به پوستهٔ تیره","words.underline":"خط کشیدن زیر این واژه‌ها در صفحه","words.underlineHelp":"نشانگر را روی واژهٔ نقطه‌چین نگه دارید یا روی آن بزنید تا معنایش را ببینید.","index.title":"AI-gile: تیم توسعهٔ هوش مصنوعی شما، روی یک بورد","index.description":"AI-gile یک بورد کانبان برای تیم‌های کدنویسی با هوش مصنوعی است. آن‌ها در خواب شما کار می‌کنند؛ شما یک دسته کوتاه کار برای تصمیم‌گیری، آزمودن و پذیرفتن تحویل می‌گیرید.","hero.logoAlt":"نماد بورد AI-gile","hero.h1.html":"تیم توسعهٔ هوش مصنوعی شما، روی یک&nbsp;بورد.","hero.alpha":"🐣 پیش‌آلفای بسته","hero.alphaTitle":"زودهنگام و ناتمام: ممنون که امتحانش می‌کنید!","hero.lede":"آن‌ها در خواب شما می‌سازند. صبح با یک دستهٔ کوتاه بیدار می‌شوید: چند پرسش، چند چیز برای آزمودن، یکی دو الماس بنفش. یک کلیک، پذیرفتن، و بازگشت به قهوه‌تان.","dl.windows":"برنامهٔ ویندوز","dl.browser":"اجرا در مرورگر","dl.soon":"به‌زودی","dl.notify":"🔔 وقتی باز شد خبرم کنید","dl.notifySmall":"آلفا یا بتا","hero.secondary":"چابک، اما تیم هرگز به قهوهٔ جلسهٔ ایستاده نیاز ندارد. (البته جلسهٔ ایستاده را هم برگزار می‌کنند.)","pitch.h2":"AI-gile در هر تعداد کلمه که بخواهید","pitch.lede":"یک طول انتخاب کنید، از یک کلمه تا ۱۴۴. هر طول توضیح خودش را دارد و برای همان اندازه نوشته شده است. لغزنده را بکشید یا از کلیدهای جهت‌نما استفاده کنید.","pitch.rangeLabel":"طول به کلمه","pitch.dice":"🎲 نسخهٔ دیگر","pitch.words.one":"{n} کلمه","pitch.words.other":"{n} کلمه","pitch.letters.one":"{n} حرف","pitch.letters.other":"{n} حرف","pitch.chars.one":"{n} نویسه","pitch.chars.other":"{n} نویسه","count.line.html.one":"{n} کارت همین حالا روی بورد است","count.line.html.other":"{n} کارت همین حالا روی بورد است","features.aria":"چه کار می‌کند","f.pile.h":"یک دسته برای شما","f.pile.html":"<b>برای شما</b> هرچه را که منتظر شماست، از همهٔ پروژه‌ها، کنار هم می‌گذارد: پرسش‌ها، چیزهایی برای آزمودن، کارهایی که فقط آدم می‌تواند انجام دهد. صف شما می‌گوید بعدی چیست و چقدر طول می‌کشد.","f.sleep.h":"تیم‌هایی که در خواب شما کار می‌کنند","f.sleep.p":"هر پروژه یک لید و یک تیم از عامل‌های هوش مصنوعی دارد. زیر یک کارت نظر بگذارید تا تیم بیدار شود، کار را انجام دهد و با مراحلی که آدم خسته هم بتواند دنبال کند تحویل بدهد.","f.tester.h":"اول یک تستر هوش مصنوعی بررسی می‌کند","f.tester.p":"پیش از آنکه چیزی به دست شما برسد، یک تستر مراحل را در یک نسخهٔ جدا از برنامه دنبال می‌کند و آنچه دیده را با اسکرین‌شات نشان می‌دهد. موردهای قبول‌شده را ورق بزنید و با یک کلیک بپذیرید.","f.proof.h":"مدرک، نه قول","f.proof.p":"هر تحویل نشان می‌دهد چه چیزی تغییر کرده: فایل‌ها، دیف، اسکرین‌شات‌ها. لازم نیست برای فهمیدن اینکه کار تمام شده تک‌تک برنامه‌ها را باز کنید.","f.chat.h":"با لیدهایتان گپ بزنید","f.chat.p":"نواری شبیه دیسکورد: یک نماد برای هر پروژه، الماس‌های بنفش برای آنچه به شما نیاز دارد. ایده‌ای برای یک لید بفرستید؛ او آن را به کارت و برنامه تبدیل می‌کند، با دکمهٔ ✅ Go.","f.tidy.h":"خودش را مرتب نگه می‌دارد","f.tidy.p":"کارت‌های مرتبط در هم ادغام می‌شوند، عنوان‌های درهم اصلاح می‌شوند و بررسی توکن کد را سبک نگه می‌دارد. جابه‌جایی کمتر، فکر کردن کمتر.","f.private.h":"مال شما، روی رایانهٔ شما","f.private.li1":"بورد روی دستگاه خودتان اجرا می‌شود و فقط به شما پاسخ می‌دهد.","f.private.li2":"پیام‌های خصوصی بین آدم‌ها سرتاسر رمزگذاری شده‌اند.","f.private.li3":"بدون حساب کاربری، بدون ردیاب، بدون کوکی.","f.lang.h":"به زبان شما","f.lang.p":"بیش از ۱۲۰ زبان، از هلندی، ولزی و ژاپنی تا دزدان دریایی، یودا و کلینگون، با یک جابه‌جایی سریع به انگلیسی برای واژه‌های برنامه‌نویسی.","tl.aria":"خط زمان از نخستین گفتگو تا نقشهٔ راه","tl.h2":"از نخستین گپ تا آنچه در پیش است","tl.lede":"تاریخ و ساعت واقعی، به وقت منطقهٔ زمانی خودتان. بعد از امروز، فقط برنامه است و تاریخی قول داده نمی‌شود.","tl.today":"امروز","tl.planned":"برنامه‌ریزی‌شده","tl.cards.one":"{n} کارت","tl.cards.other":"{n} کارت","join.h2":"همراه شوید","join.lede":"AI-gile را یک آدم کوچک و شمار زیادی عامل صبور می‌سازند. فعلاً خصوصی است، در آلفای بسته با دوستان. دوست دارید وقتی باز شد امتحانش کنید؟","join.btn":"ثبت علاقه‌مندی","join.small":"فقط ایمیل می‌زنیم، همین","footer.tag":"AI-gile. بدون ردیاب، بدون کوکی، بدون قهوهٔ جلسهٔ ایستاده.","footer.licence":"مجوز کسب‌وکار","footer.status":"وضعیت","footer.privacy":"چه چیزی نگه می‌داریم","form.sending":"در حال ارسال…","form.failed":"نشد: بعداً دوباره امتحان کنید.","form.offline":"به AI-gile دسترسی پیدا نشد: بعداً دوباره امتحان کنید.","form.keep":"فقط برای پاسخ دادن به شما از آن استفاده می‌کنیم و بعد پاکش می‌کنیم. بدون ردیاب، بدون کوکی.","form.keepLink":"چه چیزی نگه می‌داریم","interest.title":"AI-gile: وقتی آلفا باز شد خبرم کنید","interest.description":"ایمیل‌تان را بگذارید تا وقتی آلفا یا بتای بستهٔ AI-gile باز شد باخبر شوید.","interest.h1":"🔔 وقتی باز شد خبرم کنید","interest.lede":"AI-gile در پیش‌آلفای بسته است. ایمیل‌تان را بگذارید تا یک بار، وقتی برای شما جا باز شد، برایتان بنویسیم.","interest.email":"ایمیل شما","interest.which":"کدام آزمایش؟","interest.alpha":"آلفای بسته: زودهنگام، خام، پر از تغییر","interest.beta":"بتا: پایدارتر، دیرتر","interest.both":"هرکدام، هرکدام زودتر باز شد","interest.submit":"مرا در فهرست بگذارید","interest.thanks":"ممنون! در فهرست هستید.","licence.title":"AI-gile: مجوز کسب‌وکار","licence.description":"AI-gile را در کسب‌وکارتان به کار می‌برید؟ برای مجوز رایگان کسب‌وکار درخواست دهید.","licence.h1":"📜 مجوز کسب‌وکار","licence.lede":"AI-gile را سر کار به کار می‌برید؟ بگویید کی هستید و چه می‌کنید. اگر کار شما به دنیا کمکی می‌کند، مجوز رایگان است.","licence.company":"شرکت","licence.website":"وب‌سایت","licence.what":"چه می‌کنید","licence.how":"چطور به دنیا کمک می‌کند","licence.email":"ایمیل","licence.submit":"درخواست","licence.thanks":"ممنون! با ایمیل پاسخ می‌دهیم.","status.title":"وضعیت AI-gile","status.h1":"وضعیت AI-gile","status.quiet":"همه‌چیز آرام است","status.intro":"آیا AI-gile همین حالا کار می‌کند؟ این صفحه هر ۵ دقیقه وب‌سایت، اشتراک‌گذاری تابلو، تماس‌ها و دانلود را بررسی می‌کند.","status.up":"کار می‌کند (پاسخ در {ms} میلی‌ثانیه)","status.slow":"به آخرین بررسی پاسخ نداد، دوباره تلاش می‌شود","status.down":"از کار افتاده: به دو بررسی آخر پاسخ نداد","status.svc.web":"وب‌سایت","status.svc.web.offers":"همین سایت: AI-gile چیست، و فرم اعلام علاقه‌مندی","status.svc.boards":"اشتراک‌گذاری تابلو","status.svc.boards.offers":"تابلوهای عمومی، پیام‌های میان دوستان و دعوت‌ها","status.svc.calls":"تماس‌ها","status.svc.calls.offers":"صدا، تصویر و اشتراک‌گذاری صفحه در AI-gile","status.svc.download":"دانلود","status.svc.download.offers":"نصب‌کنندهٔ Windows و پیوندهای دعوت","status.checking":"در حال بررسی…","status.offline":"فعلاً به سرویس وضعیت دسترسی نیست (دوباره تلاش می‌شود)","status.updated":"به‌روز شد {ago}","status.justNow":"همین الان","status.min":"{n} دقیقه پیش","status.hours":"{n} ساعت پیش","status.days":"{n} روز پیش","privacy.title":"AI-gile: چه چیزی نگه می‌داریم","privacy.h1":"چه چیزی نگه می‌داریم","privacy.lede":"خلاصه: فقط آنچه برایمان می‌فرستید، و نه برای مدتی طولانی.","privacy.only":"فقط آنچه برایمان می‌فرستید: آنچه در یک فرم می‌نویسید، مثل ایمیلتان. هیچ چیز دیگری دربارهٔ شما.","privacy.sealed":"مهر و موم می‌شود تا سرور ما نتواند آن را بخواند: در مرورگر خودتان، پیش از آنکه فرستاده شود (در مرورگرهای قدیمی‌تر، همان لحظه‌ای که می‌رسد). فقط تابلوی خود ما می‌تواند آن را باز کند.","privacy.server":"به‌محض اینکه به تابلوی ما برسد، از سرور پاک می‌شود. هر چیزی که پس از ۳۰ روز هنوز آنجا مانده باشد، به هر حال پاک می‌شود.","privacy.board":"فقط تا زمانی که به شما پاسخ بدهیم آن را روی تابلوی خودمان نگه می‌داریم، بعد از آنجا هم پاکش می‌کنیم.","privacy.none":"بدون ردیاب، بدون کوکی، بدون ابزار آمارگیری.","privacy.local":"زبان شما و انتخاب حالت روشن یا تیره در مرورگر خودتان می‌ماند. هرگز برای ما فرستاده نمی‌شود.","privacy.ask":"می‌خواهید زودتر پاک شود؟ به ایمیل ما پاسخ دهید و بگویید.","live.h2":"ساخته‌شدنش را زنده تماشا کنید","live.caption":"هر کارت پنهان است: شکل کار را می‌بینید، نه کلمات را.","live.watching.one":"زنده: {n} نفر در حال تماشا","live.watching.other":"زنده: {n} نفر در حال تماشا","live.last.now":"آخرین کارت همین الان جابه‌جا شد","live.last.min.one":"آخرین کارت {n} دقیقه پیش جابه‌جا شد","live.last.min.other":"آخرین کارت {n} دقیقه پیش جابه‌جا شد","live.last.hour.one":"آخرین کارت {n} ساعت پیش جابه‌جا شد","live.last.hour.other":"آخرین کارت {n} ساعت پیش جابه‌جا شد","live.last.day.one":"آخرین کارت {n} روز پیش جابه‌جا شد","live.last.day.other":"آخرین کارت {n} روز پیش جابه‌جا شد","live.offline":"تابلوی زنده کمی استراحت می‌کند. به‌زودی دوباره سر بزنید.","live.cols":"بک‌لاگ|برای انجام|در حال انجام|بررسی تیم|برای تست شما|برای تیم|انجام‌شده"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["کانبان.","ربات‌ها.","سپرده‌شده."]},{"n":2,"texts":["کانبان ربات‌ها.","عامل‌ها، منظم.","ایده‌ها، ساخته‌شده."]},{"n":3,"texts":["کانبان برای ربات‌ها.","ایده می‌شود قابلیت.","کانبان رایگان عامل‌ها."]},{"n":5,"texts":["بورد کانبانی که عامل‌ها می‌گردانند.","شما می‌نویسید، عامل‌ها می‌سازند.","رایگان، محلی، آزموده، کمی بامزه."]},{"n":8,"texts":["یک بورد کانبان رایگان برای کار عامل‌های هوش مصنوعی.","ایده بنویسید. عامل‌ها می‌سازند. شما می‌پذیرید.","چابکی برای یک آدم و ربات‌های صبور فراوان."]},{"n":13,"texts":["بورد کانبانی روی رایانهٔ شما که عامل‌های هوش مصنوعی کارت‌ها را برمی‌دارند و انجام می‌دهند.","ایده‌ای بنویسید. تیمی از عامل‌ها آن را می‌سازد. یک تستر هم بررسی‌اش می‌کند.","رایگان، بدون حساب، بدون ردیاب: یک بورد، چند ربات، و شما در مقام فرمانده."]},{"n":21,"texts":["AI-gile یک بورد کانبان برای کار با عامل‌های کدنویس هوش مصنوعی است. آن‌ها کارت‌ها را برمی‌دارند؛ شما می‌آزمایید و می‌پذیرید.","هر پروژه یک لید و یک تیم از عامل‌های هوش مصنوعی می‌گیرد. زیر هر کارتی نظر بگذارید و تیم بلافاصله دست‌به‌کار می‌شود.","یک بورد کارهای شخصی و رایگان که روی رایانهٔ خودتان اجرا می‌شود. کارگرها ربات‌اند. کسی که می‌گوید بله، شما هستید."]},{"n":34,"texts":["ایده‌هایتان را روی بورد می‌گذارید. تیمی از عامل‌های هوش مصنوعی آن‌ها را به قابلیت‌های کارا تبدیل می‌کند، می‌آزماید و با مراحل امتحان تحویلتان می‌دهد. تا شما نگویید، هیچ چیز تمام‌شده حساب نمی‌شود.","AI-gile یک بورد کانبان خانگی است که ریچ با کمک بسیار همان عامل‌هایی ساخت که حالا مدیریتشان می‌کند. رایگان است، روی رایانهٔ شما اجرا می‌شود و میان دوستان دست‌به‌دست می‌شود، نه اینکه فروخته شود.","یک بورد کانبان معمولی را تصور کنید، با ستون‌هایی از «بک‌لاگ» تا «انجام‌شده»، جز اینکه کارت‌ها را عامل‌های هوش مصنوعی برمی‌دارند. پیشرفت را گزارش می‌دهند، وقتی گیر کنند می‌پرسند، و همیشه منتظر تأیید شما می‌مانند."]},{"n":55,"texts":["AI-gile یک بورد کانبان است که تیمش از عامل‌های هوش مصنوعی ساخته شده. هر پروژه یک لید دارد که کار را برنامه‌ریزی می‌کند و کمک‌هایی که آن را می‌سازند. وقتی قابلیتی آماده شد، یک تستر هوش مصنوعی امتحانش می‌کند و اسکرین‌شات می‌گیرد، بعد به دستهٔ شما می‌رسد. بپذیریدش، یا نظر بگذارید تا دوباره رویش کار کنند.","این پروژه راه یک نفر بود برای دنبال کردن چندین جلسهٔ کدنویسی با هوش مصنوعی در یک زمان، و کم‌کم به یک بورد درست‌وحسابی تبدیل شد. روی دستگاه شما اجرا می‌شود، حساب نمی‌خواهد و ردیاب ندارد. برای دوستان و آدم‌های کنجکاو رایگان است. هنوز هم ناتمام است، پس منتظر لبه‌های زبر و غافلگیری‌های گاهی باشید.","این هم روایت صادقانه. هنوز باید خودتان ایده بدهید، و هنوز باید خودتان نتیجه را بررسی کنید. AI-gile هرچه را میان این دو است انجام می‌دهد: کارت‌ها را مرتب نگه می‌دارد، وقتی نظر می‌گذارید عامل درست را بیدار می‌کند، دقیقاً نشان می‌دهد چه چیز تغییر کرده، و همه را در یک دستهٔ کوتاه برای شما می‌گذارد."]},{"n":89,"texts":["AI-gile یک بورد کانبان رایگان است که روی رایانهٔ خودتان اجرا می‌کنید. به‌جای آدم‌ها، هر پروژه یک تیم از عامل‌های هوش مصنوعی دارد: یک لید که ایده‌های شما را به کارت و برنامه تبدیل می‌کند، و کمک‌هایی که کارت‌ها را به ترتیب اولویت برمی‌دارند. وقتی چیزی ساخته شد، یک تستر هوش مصنوعی مراحل آزمون را دنبال می‌کند و آنچه دیده را نشان شما می‌دهد. بعد در یک دسته به نام «برای شما» منتظر می‌ماند. می‌پذیریدش، یا نظر می‌گذارید و تیم دوباره تلاش می‌کند. بدون شما هیچ چیز به «انجام‌شده» نمی‌رسد.","چند قابلیت که شاید انتظارشان را نداشته باشید. نگهبان شب در خواب شما ستون «برای انجام» را پر نگه می‌دارد و کارت‌هایی را برمی‌گزیند که به پاسخ شما نیاز ندارند. شمارندهٔ توکن نشان می‌دهد عامل‌ها امروز و این هفته چقدر مصرف کرده‌اند، و «حالت بدون توکن» به آن‌ها می‌گوید خرج کردن را متوقف کنند. می‌توانید به دوستان پیام بدهید و پیام‌های خصوصی سرتاسر رمزگذاری شده‌اند. بورد حدود ۱۲۰ زبان حرف می‌زند، از جمله هلندی، فلاندری، دزدان دریایی و کلینگون. هیچ‌کدام یک ریال هم خرج ندارد و کسی هم نمی‌خواهد آن را به شما بفروشد.","AI-gile یک پروژهٔ کوچک و شخصی است، نه یک شرکت. ریچ می‌خواست از چند پروژهٔ کدنویسی با هوش مصنوعی خبر داشته باشد، بی‌آنکه برای دیدن وضعیتشان هر برنامه را باز کند. پس او و عامل‌ها برایش یک بورد ساختند و بعد با همان بورد باقی‌اش را ساختند. در پیش‌آلفای بسته است، یعنی کار می‌کند، بیشتر وقت‌ها، برای مشتی دوست. صفحهٔ قیمت ندارد، خبرنامه ندارد و برنامهٔ رشد ندارد. اگر به نظرتان به کار می‌آید، می‌توانید وقتی کمی بیشتر باز شد درخواست امتحان کردنش را بدهید."]},{"n":144,"texts":["AI-gile یک بورد کانبان برای یک آدم و تعداد زیادی عامل هوش مصنوعی است. روی رایانهٔ خودتان اجرا می‌شود و کاملاً رایگان است. پروژه اضافه می‌کنید و هر پروژه یک لید و یک تیم کوچک می‌گیرد. با لید گپ می‌زنید، کمی شبیه دیسکورد، و ایده‌ای را شرح می‌دهید؛ لید آن را به کارت و برنامه تبدیل می‌کند و منتظر می‌ماند تا شما Go را بزنید. تیم کارت‌ها را به ترتیب اولویت پیش می‌برد، با یک خط فرمان ساده که برای مدل‌های زبانی ساخته شده. پیش از آنکه چیزی نزد شما برگردد، یک تستر هوش مصنوعی مراحل را در یک نسخهٔ جدا از برنامه دنبال می‌کند و یک اسکرین‌شات ضمیمه می‌کند. کار تمام‌شده با فایل‌های تغییرکرده و دیف در دستهٔ شما می‌نشیند. می‌پذیریدش، یا نظری می‌گذارید و تیم بیدار می‌شود و دوباره تلاش می‌کند. فقط شما می‌توانید کارتی را به «انجام‌شده» ببرید.","یک روز با AI-gile، تقریباً. غروب چند نظر می‌گذارید: این دکمه جایش غلط است، آن فهرست باید مرتب شود، می‌شود یک حالت تیره هم داشته باشیم. می‌روید بخوابید. عامل‌ها نظرها را می‌خوانند، تغییرها را می‌دهند، می‌آزمایند و تحویلتان می‌دهند. اگر «برای انجام» خالی شود، نگهبان شب آن را از بک‌لاگ پر می‌کند، با کارت‌هایی که به پاسخ شما نیاز ندارند. صبح یک دستهٔ کوتاه آماده است: دو سه پرسش و چند چیز برای امتحان، هرکدام با مراحلی که آدم خواب‌آلود هم بتواند دنبال کند و یک اسکرین‌شات از کار کردنش. کلیک‌کنان می‌گذرید، خوب‌ها را می‌پذیرید و بقیه را پس می‌فرستید. شمارندهٔ توکن نشان می‌دهد این همه چقدر مصرف داشته، و «حالت بدون توکن» برای هفته‌های کم‌بضاعت است. بعد صبحانه می‌خورید، کاری که عامل‌ها هنوز نمی‌توانند در آن کمکتان کنند.","اول، آنچه AI-gile نیست. استارتاپ نیست، برای فروش نیست و کسی داده‌های شما را جمع نمی‌کند. یک بورد رایگان است که روی رایانهٔ شما اجرا می‌شود، بدون حساب، بدون ردیاب و بدون کوکی. آنچه هست: یک جای مرتب برای دیدن همهٔ پروژه‌های کدنویسی با هوش مصنوعی در یک نگاه، با تیمی از عامل‌ها که کارت‌ها را انجام می‌دهند و شما که تصمیم می‌گیرید. کارت‌های مرتبط را در هم ادغام می‌کند، عنوان‌های درهم را درست می‌کند و مراقب است کد سبک بماند. حدود ۱۲۰ زبان حرف می‌زند، از هلندی و فلاندری تا دزدان دریایی و کلینگون. دوستان می‌توانند به هم پیام بدهند، خصوصی و رمزگذاری‌شده. ریچ و شمار زیادی عامل صبور ساختندش، بیشتر با استفاده از خودش. در پیش‌آلفای بسته است، پس جاهایی هنوز خام است. اگر به نظرتان سرگرم‌کننده می‌آید، مؤدبانه درخواست کنید و شاید زودتر وارد شوید."]}],"quips":{"1":"یک کلمه. جسورانه. شاید بیش از حد.","3":"سه کلمه. همین حالا صادق‌تر از بیشتر صفحه‌های محصول.","8":"هشت کلمه. هنوز کوتاه‌تر از یک جلسهٔ ایستاده.","21":"راستی، طول‌ها امتیاز داستان‌اند. معلوم است که هستند.","55":"پنجاه‌وپنج کلمه. تا شما این را خواندید، دو کارت تمام شد.","144":"این بلندترین بود. ۲۳۳ وجود ندارد. عامل‌ها رفته‌اند بخوابند."}},"timeline":{"first-idea.name":"نخستین ایده","first-idea.line":"نخستین گفتگو، پیش از آنکه حتی یک خط کد وجود داشته باشد.","first-board.name":"نخستین بورد","first-board.line":"بوردی که ساخته شدن خودش را دنبال می‌کند: کارت، ستون، کشیدن و رها کردن، پروژه.","team-roles.name":"تیم و نقش‌ها","team-roles.line":"نمایه‌های عامل، قالب‌های تیم، فضاها و اینکه چه کسی چه می‌کند.","install.name":"نصب و انتشار","install.line":"یک فایل زیپ که دوستی بتواند نصبش کند، به‌روزرسانی خودکار، کانال‌ها و بازگشت به نسخهٔ قبل.","usage-saver.name":"صرفه‌جویی در مصرف","usage-saver.line":"سنجیدن هزینهٔ هر اجرا، سبک نگه داشتن کد، حفظ سقف مصرف شما.","friends.name":"دوستان و اشتراک‌گذاری","friends.line":"پیام‌های خصوصی، رلهٔ درهم‌ریخته، دعوت‌نامه‌ها، نقش‌ها و پروژه‌های مشترک.","languages.name":"زبان‌ها","languages.line":"همهٔ متن‌های صفحه در یک فایل زبان، با هلندی و فلاندری در آغاز.","ai-tester.name":"تستر هوش مصنوعی","ai-tester.line":"یک تستر هر تحویل را اول بررسی می‌کند و آنچه دیده را نشان می‌دهد.","website.name":"وب‌سایت","website.line":"aigile.lol، صفحهٔ معرفی و همین خط زمان.","streaming.name":"گپ و پخش زنده","streaming.line":"دیسکورد، توئیچ، OBS، حالت استریمر، گیف و ایموجی.","no-ai.name":"نسخهٔ بدون هوش مصنوعی","no-ai.line":"بوردی برای کسانی که بدون هوش مصنوعی کد می‌نویسند، و بوردهای عمومی.","night-watch.name":"نگهبان شب","night-watch.line":"یک نگهبان و یک اسکرام مستر تیم‌ها را در خواب شما سرِ کار نگه می‌دارند.","p-more.name":"همهٔ چیزهای دیگر","p-more.line":"ایده‌های کوچک‌تر که هنوز منتظر نوبتشان هستند.","p-android.name":"تلفن و اندروید","p-android.line":"دسترسی به بورد از تلفن، و بعد یک برنامهٔ بومی اندروید.","p-release.name":"آلفا و بعد از آن","p-release.line":"آلفای بسته، سایت زنده، و بعد بتا.","p-languages.name":"زبان‌های بیشتر","p-languages.line":"بیش از صد زبان، و یک حالت غوطه‌وری برای زبان‌آموزان.","p-engines.name":"موتورهای هوش مصنوعی بیشتر","p-engines.line":"برای هر عامل Claude، Codex یا Gemini را انتخاب کنید.","p-pro.name":"رویهٔ حرفه‌ای","p-pro.line":"برچسب ریسک، دروازهٔ ادغام، کارت حادثه و نرده‌های ایمنی.","p-self.name":"مراقبت از شما","p-self.line":"حالت خستگی، یادآور مراقبت از خود و ۴:۲۰.","p-servers.name":"سرورها و مقیاس","p-servers.line":"تنظیمات سراسری سرور، نقش‌ها و برنامه‌ریزی برای رشد.","p-livestream.name":"امکانات پخش زنده","p-livestream.line":"گپ توئیچ، ایموجی سفارشی و نمای زندهٔ عمومی."},"words":{"button":"📖 واژه‌های برنامه‌نویسی","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"جستجوی یک واژه…","none":"هیچ واژه‌ای پیدا نشد.","close":"بستن","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"ریپو","text":"پوشه‌ی کد پروژه و تمام تاریخچه‌ی کامیت‌هایش، که معمولاً در GitHub هم نگه داشته می‌شود.","also":["مخزن","ریپو","repo","repository"]},{"id":"branch","g":"build","word":"برنچ","text":"یک خط کار جدا در کد، تا بتوان بدون دست زدن به نسخه‌ی اصلی تغییر داد.","also":["برنچ‌ها","برنچ","branch","branches"]},{"id":"commit","g":"build","word":"کامیت","text":"یک عکس ذخیره‌شده از کد، با یادداشتی کوتاه از آنچه تغییر کرد. همیشه می‌توانید به یکی از آن‌ها برگردید.","also":["کامیت‌ها","کامیت","commit","commits"]},{"id":"push","g":"build","word":"پوش","text":"فرستادن عکس‌های ذخیره‌شده (کامیت‌ها) از این رایانه به GitHub، تا پشتیبان گرفته و به اشتراک گذاشته شوند."},{"id":"merge","g":"build","word":"مرج","text":"برگرداندن تغییرهای یک برنچ به نسخه‌ی اصلی."},{"id":"pr","g":"build","word":"پول ریکوئست","text":"درخواست برای بررسی و ادغام تغییرهای یک برنچ در نسخه‌ی اصلی.","also":["PR"]},{"id":"refactor","g":"build","word":"بازآرایی","text":"مرتب کردن کد بدون تغییر آنچه انجام می‌دهد: فایل‌های کوچک‌تر، نام‌های روشن‌تر، تکرار کمتر."},{"id":"bug","g":"build","word":"باگ","text":"چیزی که آن‌طور که باید کار نمی‌کند.","also":["باگ‌ها","باگ","bug","bugs"]},{"id":"test","g":"build","word":"تست","text":"امتحان کردن کار تمام‌شده، پیش از قبول کردنش، تا ببینید همان کاری را که خواسته شده انجام می‌دهد.","also":["تست‌ها","تستی","تست کردن","test","tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"دیپلوی","text":"زنده کردن نسخه‌ی جدید، مثلاً روی سروری که مردم از آن استفاده می‌کنند."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"بک‌لاگ","text":"ایده‌ها و کارهایی که هنوز برنامه‌ریزی نشده‌اند. تا به «برای انجام» نروند، رویشان کار نمی‌شود."},{"id":"sprint","g":"team","word":"اسپرینت","text":"یک بازه‌ی کوتاه کار (اغلب یکی دو هفته) با مجموعه‌ای از کارت‌های توافق‌شده برای تمام کردن.","also":["اسپرینت‌ها","اسپرینت","sprint","sprints"]},{"id":"standup","g":"team","word":"استندآپ","text":"یک گزارش سریع: هر عضو تیم چه کرد، بعد چه می‌کند و چه چیزی جلویش را گرفته.","also":["استندآپ‌ها","استند‌آپ","standup","stand-up","stand-ups"]},{"id":"kanban","g":"team","word":"کانبان","text":"بوردی با ستون‌ها (برای انجام، در حال انجام، انجام‌شده) که کارت‌ها در حین کار از راست به چپ در آن جلو می‌روند."},{"id":"wip","g":"team","word":"سقف WIP","text":"کار در جریان: بیشترین تعداد کارت در یک ستون، تا تیم پیش از شروع کار تازه کارها را تمام کند.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"عامل","text":"هوش مصنوعی‌ای که خودش روی یک تسک کار می‌کند: کد را می‌خواند، تغییر می‌دهد، بررسی‌ها را اجرا می‌کند و گزارش می‌دهد.","also":["عامل‌ها","عامل","agent","agents"]},{"id":"token","g":"team","word":"توکن","text":"واحدی که مصرف هوش مصنوعی با آن شمرده می‌شود: تقریباً چند حرف متن که خوانده یا نوشته شده. توکن کمتر، سهم بیشتری از پلن باقی می‌ماند.","also":["توکن‌ها","توکن","token","tokens"]},{"id":"hook","g":"team","word":"هوک","text":"دستور کوچکی که در لحظه‌ای مشخص خودش اجرا می‌شود، مثلاً وقتی نشست هوش مصنوعی شروع می‌شود، تا تیم نظرهای شما را بشنود.","also":["هوک‌ها","هوک","hook","hooks"]}]}};
